int isspace(int c);
int isdigit(int c);
int isalpha(int c);
int isalnum(int c);
int iscntrl(int c);
int islower(int c);
int isupper(int c);
int isprint(int c);
int ispunct(int c);
int isgraph(int c);
int isxdigit(int c);

/* Memory management */
void* malloc(size_t size);
void* calloc(size_t nmemb, size_t size);
