#!/usr/bin/env node
// One-off ELF analysis for doomgeneric_mips (MIPS32r2 LE).
const fs = require('fs');
const buf = fs.readFileSync(process.argv[2] || 'doomgeneric_mips');

const U8 = (o) => buf.readUInt8(o);
const U16 = (o) => buf.readUInt16LE(o);
const U32 = (o) => buf.readUInt32LE(o);
const I32 = (o) => buf.readInt32LE(o);
const U64 = (o) => { const lo = buf.readUInt32LE(o); const hi = buf.readUInt32LE(o+4); return hi*0x100000000+lo; };

console.log('--- ELF Header ---');
console.log('magic:', buf.slice(0,4));
const ei_class = U8(4); // 1=32bit 2=64bit
const ei_data = U8(5);  // 1=LE 2=BE
console.log('class:', ei_class, ei_class===1?'32-bit':ei_class===2?'64-bit':'?');
console.log('data:', ei_data, ei_data===1?'LE':ei_data===2?'BE':'?');
const is64 = ei_class === 2;
const e_type = U16(16);
const e_machine = U16(18);
console.log('e_type:', e_type, e_type===2?'EXEC':e_type===3?'DYN':'?');
console.log('e_machine:', e_machine, e_machine===8?'MIPS':'?');
const e_entry = U32(is64?24:24);
const e_phoff = is64?U64(32):U32(28);
const e_shoff = is64?U64(40):U32(32);
const e_phentsize = U16(is64?54:42);
const e_phnum = U16(is64?56:44);
const e_shentsize = U16(is64?58:46);
const e_shnum = U16(is64?60:48);
const e_shstrndx = U16(is64?62:50);
console.log('e_entry:', '0x'+e_entry.toString(16));
console.log('e_phoff:', e_phoff, 'e_phnum:', e_phnum, 'e_phentsize:', e_phentsize);
console.log('e_shoff:', e_shoff, 'e_shnum:', e_shnum, 'e_shentsize:', e_shentsize, 'e_shstrndx:', e_shstrndx);

console.log('\n--- Program Headers ---');
const phs = [];
for (let i=0;i<e_phnum;i++){
  const off = e_phoff + i*e_phentsize;
  let p_type, p_offset, p_vaddr, p_paddr, p_filesz, p_memsz, p_flags, p_align;
  if (is64){
    p_type=U32(off); p_flags=U32(off+4); p_offset=U64(off+8); p_vaddr=U64(off+16); p_paddr=U64(off+24); p_filesz=U64(off+32); p_memsz=U64(off+40); p_align=U64(off+48);
  } else {
    p_type=U32(off); p_offset=U32(off+4); p_vaddr=U32(off+8); p_paddr=U32(off+12); p_filesz=U32(off+16); p_memsz=U32(off+20); p_flags=U32(off+24); p_align=U32(off+28);
  }
  phs.push({p_type,p_offset,p_vaddr,p_filesz,p_memsz,p_flags,p_align});
  const tname = {1:'LOAD',2:'DYNAMIC',3:'INTERP',4:'NOTE',6:'PHDR',7:'TLS',0x70000000:'MIPS_REGINFO',0x70000002:'MIPS_ABIFLAGS'}[p_type]||('0x'+p_type.toString(16));
  console.log(`[${i}] ${tname} off=0x${p_offset.toString(16)} vaddr=0x${p_vaddr.toString(16)} filesz=0x${p_filesz.toString(16)} memsz=0x${p_memsz.toString(16)} flags=${p_flags} align=0x${p_align.toString(16)}`);
}

// Section headers
console.log('\n--- Section Headers ---');
// read shstrtab
function readStr(strtabOff, idx){ let s=''; let o=strtabOff+idx; while(buf[o]!==0){ s+=String.fromCharCode(buf[o]); o++; } return s; }
const shstr_off = (is64? U64(e_shoff + e_shstrndx*e_shentsize + 24) : U32(e_shoff + e_shstrndx*e_shentsize + 16));
const sections = [];
let bssEnd = 0, minVaddr = Infinity, maxVaddr = 0;
for (let i=0;i<e_shnum;i++){
  const off = e_shoff + i*e_shentsize;
  let sh_name, sh_type, sh_flags, sh_addr, sh_offset, sh_size;
  if (is64){ sh_name=U32(off); sh_type=U32(off+4); sh_flags=U64(off+8); sh_addr=U64(off+16); sh_offset=U64(off+24); sh_size=U64(off+32); }
  else { sh_name=U32(off); sh_type=U32(off+4); sh_flags=U32(off+8); sh_addr=U32(off+12); sh_offset=U32(off+16); sh_size=U32(off+20); }
  const name = readStr(shstr_off, sh_name);
  sections.push({name, sh_type, sh_flags, sh_addr, sh_offset, sh_size});
}
for (const s of sections){
  const alloc = (s.sh_flags & 2) !== 0; // SHF_ALLOC
  if (alloc){
    if (s.sh_addr < minVaddr) minVaddr = s.sh_addr;
    if (s.sh_addr + s.sh_size > maxVaddr) maxVaddr = s.sh_addr + s.sh_size;
  }
  if (s.name && (alloc || s.sh_type===8 /*NOBITS*/ || s.name==='.bss'))
    console.log(`${s.name.padEnd(20)} type=${s.sh_type} addr=0x${s.sh_addr.toString(16)} off=0x${s.sh_offset.toString(16)} size=0x${s.sh_size.toString(16)} flags=0x${s.sh_flags.toString(16)}`);
}
console.log('ALLOC range: 0x'+minVaddr.toString(16)+' .. 0x'+maxVaddr.toString(16), '('+(maxVaddr-minVaddr)+' bytes,'+((maxVaddr-minVaddr)/1024/1024).toFixed(1)+' MB)');

// Symbols
function findSymtab(){
  for (const s of sections){ if (s.name==='.symtab') return s; }
  for (const s of sections){ if (s.sh_type===2) return s; }
  return null;
}
const symtab = findSymtab();
if (symtab){
  const strtabSec = sections[symtab.sh_type===2 ? sections.indexOf(symtab) : -1];
  // find link: symtab link is strtab index. We don't have link here directly; find .strtab by name
  const strtab = sections.find(s=>s.name==='.strtab') || sections.find(s=>s.name==='.dynstr');
  const strOff = strtab ? strtab.sh_offset : 0;
  const symSize = is64 ? 24 : 16;
  const count = symtab.sh_size / symSize;
  const want = ['__start','_start','main','doomgeneric_Create','doomgeneric_Tick','DG_DrawFrame','DG_Init','DG_ScreenBuffer','heap','heap_pos','malloc','free','writeBMPFile','fopen','fwrite','real_syscall6','DG_GetTicksMs','DG_GetKey'];
  console.log('\n--- Key Symbols (symtab count='+count+') ---');
  const found = {};
  for (let i=0;i<count;i++){
    const off = symtab.sh_offset + i*symSize;
    let st_name, st_value, st_size, st_info;
    if (is64){ st_name=U32(off); st_info=U8(off+4); st_value=U64(off+8); st_size=U64(off+16); }
    else { st_name=U32(off); st_value=U32(off+4); st_size=U32(off+8); st_info=U8(off+12); }
    const nm = readStr(strOff, st_name);
    if (!nm) continue;
    for (const w of want){ if (nm===w){ found[nm]={value:st_value,size:st_size,info:st_info}; } }
  }
  for (const w of want){
    if (found[w]) console.log(`${w.padEnd(22)} = 0x${found[w].value.toString(16)}  size=${found[w].size}`);
    else console.log(`${w.padEnd(22)} = (not found)`);
  }
}

